1	package main
2	
3	import (
4		"os"
5		"path/filepath"
6		"strings"
7		"testing"
8	)
9	
10	// captureStdout runs fn with os.Stdout redirected to a temp file and returns
11	// everything it wrote.
12	func captureStdout(t *testing.T, fn func()) string {
13		t.Helper()
14		orig := os.Stdout
15		tmp, err := os.CreateTemp(t.TempDir(), "stdout-*")
16		if err != nil {
17			t.Fatal(err)
18		}
19		os.Stdout = tmp
20		defer func() { os.Stdout = orig }()
21		fn()
22		if err := tmp.Close(); err != nil {
23			t.Fatal(err)
24		}
25		data, err := os.ReadFile(tmp.Name())
26		if err != nil {
27			t.Fatal(err)
28		}
29		return string(data)
30	}
31	
32	// TestSnapshotCreateCLIRejectsCorruptIndex applies the same rules at the
33	// command line as the Go API: a healthy create keeps its existing success
34	// line, while an unusable current mapping fails with an error naming the
35	// snapshot and the index, prints no success line, and leaves no snapshot.
36	func TestSnapshotCreateCLIRejectsCorruptIndex(t *testing.T) {
37		root := filepath.Join(t.TempDir(), "vault")
38		input := filepath.Join(t.TempDir(), "a.txt")
39		if err := os.WriteFile(input, []byte("payload"), 0o644); err != nil {
40			t.Fatal(err)
41		}
42		if err := run([]string{"init", "--root", root}); err != nil {
43			t.Fatal(err)
44		}
45		if err := run([]string{"put", "--root", root, "--name", "a.txt", "--file", input}); err != nil {
46			t.Fatal(err)
47		}
48	
49		out := captureStdout(t, func() {
50			if err := run([]string{"snapshot", "create", "--root", root, "--name", "good"}); err != nil {
51				t.Fatal(err)
52			}
53		})
54		if !strings.Contains(out, "snapshot good created with 1 entries") {
55			t.Fatalf("successful create must keep its existing success line, got %q", out)
56		}
57	
58		// A null entries mapping is corruption, never an empty snapshot.
59		if err := os.WriteFile(filepath.Join(root, "index.json"),
60			[]byte(`{"entries":null}`), 0o644); err != nil {
61			t.Fatal(err)
62		}
63		var createErr error
64		out = captureStdout(t, func() {
65			createErr = run([]string{"snapshot", "create", "--root", root, "--name", "bad"})
66		})
67		if createErr == nil {
68			t.Fatal("expected create over a corrupt index to fail")
69		}
70		if !strings.Contains(createErr.Error(), `cannot create snapshot "bad"`) {
71			t.Fatalf("error %q does not name the snapshot being created", createErr)
72		}
73		if !strings.Contains(createErr.Error(), "missing entries mapping") {
74			t.Fatalf("error %q does not say why the index is unusable", createErr)
75		}
76		if out != "" {
77			t.Fatalf("failed create must print nothing, got %q", out)
78		}
79	
80		listOut := captureStdout(t, func() {
81			if err := run([]string{"snapshot", "list", "--root", root}); err != nil {
82				t.Fatal(err)
83			}
84		})
85		if !strings.Contains(listOut, "good\t1\n") || strings.Contains(listOut, "bad") {
86			t.Fatalf("failed create left a snapshot behind: %q", listOut)
87		}
88	}
89	
90	// TestSnapshotRestoreCLI confirms the command-line entry point follows the
91	// same restore rules as the Go API: a damaged record fails (the caller exits
92	// non-zero and no success line is printed), while a healthy record restores
93	// and prints the success line.
94	func TestSnapshotRestoreCLI(t *testing.T) {
95		root := filepath.Join(t.TempDir(), "vault")
96		input := filepath.Join(t.TempDir(), "a.txt")
97		if err := os.WriteFile(input, []byte("payload"), 0o644); err != nil {
98			t.Fatal(err)
99		}
100	
101		if err := run([]string{"init", "--root", root}); err != nil {
102			t.Fatal(err)
103		}
104		if err := run([]string{"put", "--root", root, "--name", "a.txt", "--file", input}); err != nil {
105			t.Fatal(err)
106		}
107		if err := run([]string{"snapshot", "create", "--root", root, "--name", "s"}); err != nil {
108			t.Fatal(err)
109		}
110		if err := os.WriteFile(input, []byte("changed payload"), 0o644); err != nil {
111			t.Fatal(err)
112		}
113		if err := run([]string{"put", "--root", root, "--name", "b.txt", "--file", input}); err != nil {
114			t.Fatal(err)
115		}
116	
117		// Damage the record: null entries must not be treated as an empty snapshot.
118		if err := os.WriteFile(filepath.Join(root, "snapshots", "s.json"),
119			[]byte(`{"name":"s","entries":null}`), 0o644); err != nil {
120			t.Fatal(err)
121		}
122	
123		var restoreErr error
124		out := captureStdout(t, func() {
125			restoreErr = run([]string{"snapshot", "restore", "--root", root, "--name", "s"})
126		})
127		if restoreErr == nil {
128			t.Fatal("expected CLI restore of a damaged record to fail")
129		}
130		if !strings.Contains(restoreErr.Error(), `snapshot "s" is corrupted`) {
131			t.Fatalf("error %q does not identify the damaged snapshot", restoreErr)
132		}
