432	// TestCreateSnapshotRejectsUnusableCurrentIndex is the creation-time
433	// counterpart of the strict index rules verify and gc enforce: a snapshot is
434	// never taken from a mapping that is not itself complete and unambiguous. A
435	// bare null, an empty {}, a missing or null entries mapping, a non-object
436	// entries value, a truncated document, trailing content, any duplicate key
437	// (including a name written again through a Unicode escape), or an entry that
438	// fails the key-matches-name / legal-name / digest / non-negative-size rules
439	// must reject the whole operation. The error names the snapshot being created
440	// and says the current index is corrupt (with the duplicated key or offending
441	// artifact in the underlying reason), no snapshot is left behind, and the
442	// index bytes, existing snapshots, and objects are untouched.
443	func TestCreateSnapshotRejectsUnusableCurrentIndex(t *testing.T) {
444		goodDigest := hex.EncodeToString(sha256.New().Sum(nil))
445		validEntry := `{"name":"a","digest":"` + goodDigest + `","size":0,"createdAt":"2026-01-01T00:00:00Z"}`
446		// A JSON key naming a/b directly and the same key written with a Unicode
447		// escape (/) must collide once the strings are decoded.
448		unicodeDupIndex := `{"entries":{` +
449			`"a/b":{"name":"a/b","digest":"` + goodDigest + `","size":0,"createdAt":"2026-01-01T00:00:00Z"},` +
450			`"a` + `\` + `u002fb":{"name":"a/b","digest":"` + goodDigest + `","size":0,"createdAt":"2026-01-01T00:00:00Z"}` +
451			`}}`
452		cases := map[string]struct {
453			index       string
454			wantInError string
455		}{
456			"bare null": {
457				index:       `null`,
458				wantInError: "expected a JSON object with an entries mapping",
459			},
460			"empty object": {
461				index:       `{}`,
462				wantInError: "missing entries mapping",
463			},
464			"null entries": {
465				index:       `{"entries":null}`,
466				wantInError: "missing entries mapping",
467			},
468			"array entries": {
469				index:       `{"entries":[]}`,
470				wantInError: "cannot unmarshal",
471			},
472			"string entries": {
473				index:       `{"entries":"none"}`,
474				wantInError: "cannot unmarshal",
475			},
476			"number entries": {
477				index:       `{"entries":3}`,
478				wantInError: "cannot unmarshal",
479			},
480			"truncated document": {
481				index:       `{"entries":{`,
482				wantInError: "unexpected end of JSON input",
483			},
484			"trailing content": {
485				index:       `{"entries":{}} {}`,
486				wantInError: "invalid character",
487			},
488			"top level array": {
489				index:       `[]`,
490				wantInError: "expected a JSON object with an entries mapping",
491			},
492			"duplicate entries field": {
493				index:       `{"entries":null,"entries":{}}`,
494				wantInError: `duplicate key "entries"`,
495			},
496			"duplicate artifact name": {
497				index:       `{"entries":{"a":` + validEntry + `,"a":` + validEntry + `}}`,
498				wantInError: `duplicate key "a"`,
499			},
500			"same name through unicode escape": {
501				index:       unicodeDupIndex,
502				wantInError: `duplicate key "a/b"`,
503			},
504			"duplicate field inside entry": {
505				index:       `{"entries":{"a":{"name":"a","digest":"` + goodDigest + `","size":0,"size":1,"createdAt":"2026-01-01T00:00:00Z"}}}`,
506				wantInError: `duplicate key "size"`,
507			},
508			"entry key mismatch": {
509				index:       `{"entries":{"a":{"name":"b","digest":"` + goodDigest + `","size":0,"createdAt":"2026-01-01T00:00:00Z"}}}`,
510				wantInError: `is filed under`,
511			},
512			"entry illegal name": {
513				index:       `{"entries":{"../evil":{"name":"../evil","digest":"` + goodDigest + `","size":0,"createdAt":"2026-01-01T00:00:00Z"}}}`,
514				wantInError: `invalid entry name`,
515			},
516			"entry bad digest": {
517				index:       `{"entries":{"a":{"name":"a","digest":"XYZ","size":0,"createdAt":"2026-01-01T00:00:00Z"}}}`,
518				wantInError: "want 64 lowercase hex characters",
519			},
520			"entry negative size": {
521				index:       `{"entries":{"a":{"name":"a","digest":"` + goodDigest + `","size":-7,"createdAt":"2026-01-01T00:00:00Z"}}}`,
522				wantInError: "negative size",
523			},
524		}
525		for label, tc := range cases {
526			t.Run(label, func(t *testing.T) {
527				root := filepath.Join(t.TempDir(), "vault")
528				store := New(root)
529				keepEntry, err := store.Put("keep.txt", writeFile(t, "keep me"))
530				if err != nil {
531					t.Fatal(err)
532				}
533				if _, err := store.CreateSnapshot("keep"); err != nil {
534					t.Fatal(err)
535				}
536				// An object referenced by nothing once the mapping is replaced.
537				stray := hex.EncodeToString(sha256.New().Sum([]byte("stray")))
538				if err := os.WriteFile(filepath.Join(root, "objects", stray), []byte("stray"), 0o644); err != nil {
539					t.Fatal(err)
540				}
541				indexPath := filepath.Join(root, "index.json")
542				if err := os.WriteFile(indexPath, []byte(tc.index), 0o644); err != nil {
543					t.Fatal(err)
544				}
545				keepRecord, err := os.ReadFile(filepath.Join(root, "snapshots", "keep.json"))
546				if err != nil {
547					t.Fatal(err)
548				}
549	
550				snap, err := store.CreateSnapshot("snap")
551				if err == nil {
552					t.Fatal("expected create to be rejected")
553				}
554				if !reflect.DeepEqual(snap, Snapshot{}) {
555					t.Fatalf("failed create returned a usable snapshot: %+v", snap)
556				}
557				msg := err.Error()
558				if !strings.Contains(msg, `cannot create snapshot "snap"`) {
559					t.Fatalf("error %q does not name the snapshot being created", msg)
560				}
561				if !strings.Contains(msg, "current index") {
562					t.Fatalf("error %q does not identify the current index as the cause", msg)
563				}
564				if !strings.Contains(msg, tc.wantInError) {
565					t.Fatalf("error %q does not indicate %q", msg, tc.wantInError)
566				}
567	
568				// No new snapshot; the existing one is byte-for-byte unchanged.
569				infos, err := New(root).ListSnapshots()
570				if err != nil {
571					t.Fatal(err)
572				}
573				if len(infos) != 1 || infos[0].Name != "keep" {
574					t.Fatalf("failed create changed the snapshot set: %+v", infos)
575				}
576				gotRecord, err := os.ReadFile(filepath.Join(root, "snapshots", "keep.json"))
577				if err != nil {
578					t.Fatal(err)
579				}
580				if !reflect.DeepEqual(gotRecord, keepRecord) {
581					t.Fatal("existing snapshot record was rewritten")
582				}
583				// The corrupt index bytes and every object are untouched.
584				gotIndex, err := os.ReadFile(indexPath)
585				if err != nil {
586					t.Fatal(err)
587				}
588				if string(gotIndex) != tc.index {
589					t.Fatalf("index was rewritten\nwas: %s\nnow: %s", tc.index, gotIndex)
590				}
591				for _, path := range []string{
592					filepath.Join(root, "objects", keepEntry.Digest),
593					filepath.Join(root, "objects", stray),
594				} {
595					if _, err := os.Stat(path); err != nil {
596						t.Fatalf("object %s disappeared: %v", path, err)
597					}
598				}
599				// No temporary files left behind in the repository.
600				for _, dir := range []string{root, filepath.Join(root, "snapshots")} {
601					entries, err := os.ReadDir(dir)
602					if err != nil {
603						t.Fatal(err)
604					}
605					for _, e := range entries {
606						if strings.HasPrefix(e.Name(), ".snapshot-") || strings.HasPrefix(e.Name(), ".index-") {
607							t.Fatalf("temporary file left behind: %s", filepath.Join(dir, e.Name()))
608						}
609					}
610				}
611			})
612		}
613	}
