615	// TestCreateSnapshotErrorKindsStayDistinct makes sure an unusable current
616	// index is never confused with the snapshot name being illegal or with a
617	// snapshot of that name already existing.
618	func TestCreateSnapshotErrorKindsStayDistinct(t *testing.T) {
619		root := filepath.Join(t.TempDir(), "vault")
620		store := New(root)
621		if _, err := store.Put("a.txt", writeFile(t, "data")); err != nil {
622			t.Fatal(err)
623		}
624		if _, err := store.CreateSnapshot("dup"); err != nil {
625			t.Fatal(err)
626		}
627	
628		// Healthy index: illegal name first, no index mention.
629		_, err := store.CreateSnapshot("../escape")
630		if err == nil || !strings.Contains(err.Error(), "name must be") || strings.Contains(err.Error(), "current index") {
631			t.Fatalf("illegal-name error wrong: %v", err)
632		}
633		// Healthy index: same-named snapshot, distinct from index corruption.
634		_, err = store.CreateSnapshot("dup")
635		if err == nil || !strings.Contains(err.Error(), `snapshot "dup" already exists`) || strings.Contains(err.Error(), "current index") {
636			t.Fatalf("duplicate-snapshot error wrong: %v", err)
637		}
638	
639		// Corrupt index: the failure names the index, never "already exists"
640		// even when the snapshot name is free, and nothing is written.
641		if err := os.WriteFile(filepath.Join(root, "index.json"), []byte(`{"entries":null}`), 0o644); err != nil {
642			t.Fatal(err)
643		}
644		_, err = store.CreateSnapshot("new-name")
645		if err == nil || !strings.Contains(err.Error(), `cannot create snapshot "new-name"`) ||
646			!strings.Contains(err.Error(), "missing entries mapping") {
647			t.Fatalf("corrupt-index error wrong: %v", err)
648		}
649	}
