// errCurrentIndexCorrupt marks an index whose bytes are present but do not
// form a complete, usable name mapping.
var errCurrentIndexCorrupt = errors.New("current index is corrupt")

// errCurrentIndexUnreadable marks an index whose bytes cannot be read at all,
// as opposed to bytes that parse or validate badly.
var errCurrentIndexUnreadable = errors.New("current index cannot be read")

func (s *Store) Put(name, source string) (Entry, error) {
	if err := validateName(name); err != nil {
		return Entry{}, err
	}
	if source == "" {
		return Entry{}, errors.New("file is required")
	}
	var entry Entry
	err := s.withLock(true, func() error {
		if err := s.initLocked(); err != nil {
			return err
		}
		// Both a new name and an overwrite presuppose the whole current
		// mapping: every existing key and record must be usable before this
		// upload adds or replaces anything. This runs before the input is
		// opened and before any temporary file is staged, so a corrupt or
		// unreadable index fails the upload without a new content object, a
		// leftover temporary file, or a rewritten mapping that drops the old
		// artifact references.
		idx, err := s.loadIndexForUpload(name)
		if err != nil {
			return err
		}
		in, err := os.Open(source)
		if err != nil {
			return fmt.Errorf("cannot store %q: cannot read input file %q: %w", name, source, err)
		}
		defer in.Close()
		tmp, err := os.CreateTemp(filepath.Join(s.root, "objects"), ".upload-*")
		if err != nil {
			return err
		}
		tmpName := tmp.Name()
		defer os.Remove(tmpName)
		hash := sha256.New()
		size, copyErr := io.Copy(io.MultiWriter(tmp, hash), in)
		closeErr := tmp.Close()
		if copyErr != nil {
			return fmt.Errorf("cannot store %q: cannot read input file %q: %w", name, source, copyErr)
		}
		if closeErr != nil {
			return fmt.Errorf("cannot store %q: cannot stage upload: %w", name, closeErr)
		}
		digest := hex.EncodeToString(hash.Sum(nil))
		if err := s.placeObject(name, digest, size, tmpName); err != nil {
			return err
		}
		entry = Entry{Name: name, Digest: digest, Size: size, CreatedAt: time.Now().UTC()}
		idx.Entries[name] = entry
		return s.save(idx)
	})
	if err != nil {
		return Entry{}, err
	}
	return entry, nil
}

// loadIndexForUpload loads the current name mapping with the same strict
// rules verify and snapshot creation apply and validates every record before
// the upload is allowed to proceed. A genuine {"entries":{}} mapping is a
// healthy (empty) repository; anything else — a bare null, a missing or null
// entries mapping, a non-object mapping, a truncated document or one with
// trailing content, any duplicate key at any level (including a name written
// directly and again through Unicode escapes), or a record that fails the
// key-matches-name / legal-name / digest / non-negative-size rules — rejects
// the whole upload even when the offending record is unrelated to the name
// being uploaded. Errors always name the upload and the index problem ("is
// corrupt" versus "cannot be read"), staying distinct from an input file that
// cannot be opened and from a damaged existing content object.
func (s *Store) loadIndexForUpload(uploadName string) (index, error) {
	idx, err := s.loadStrict()
	if err != nil {
		return index{}, fmt.Errorf("cannot store %q: %w", uploadName, err)
	}
	keys := make([]string, 0, len(idx.Entries))
	for key := range idx.Entries {
		keys = append(keys, key)
	}
	sort.Strings(keys)
	for _, key := range keys {
		if err := validateEntryRecord(key, idx.Entries[key]); err != nil {
			return index{}, fmt.Errorf("cannot store %q: %w: %w", uploadName, errCurrentIndexCorrupt, err)
		}
	}
	return idx, nil
}

