	if err == nil {
		t.Fatal("expected put to fail")
	}
	if !strings.Contains(err.Error(), "current index is corrupt") {
		t.Fatalf("corrupt index must take precedence over a missing input: %v", err)
	}
	if strings.Contains(err.Error(), "input file") {
