		t.Fatalf("error %q does not name the upload", msg)
	}
	if !strings.Contains(msg, "current index cannot be read") {
		t.Fatalf("error %q does not say the index cannot be read", msg)
	}
	if strings.Contains(msg, "corrupt") {
