			index: `{"entries":{"other.txt":{"name":"wrong.txt","digest":"` + goodDigest +
				`","size":7,"createdAt":"2026-01-01T00:00:00Z"}}}`,
			wantInError: `entry "wrong.txt" is filed under "other.txt"`,
		},
